CREATE FUNCTION firstten_policy_test.gmh_session(label text)RETURNS text LANGUAGE sql STABLE AS $$SELECT result->>'sessionToken'FROM firstten_policy_test.gmh_results WHERE gmh_results.label=$1$$;
CREATE FUNCTION firstten_policy_test.gmh_doc()RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT document FROM firstten_policy_test.gmh_docs WHERE label='full'$$;
GRANT EXECUTE ON FUNCTION firstten_policy_test.gmh_session(text),firstten_policy_test.gmh_doc()TO authenticated,service_role;
SELECT ok(NOT has_table_privilege('anon','firstten_private.guest_marketing_plans','SELECT,INSERT,UPDATE,DELETE'),'anonymous has no raw marketing handoff grants');
SELECT ok(NOT has_table_privilege('authenticated','firstten_private.guest_marketing_plans','SELECT,INSERT,UPDATE,DELETE'),'account identity gains no private guest plan access');
SELECT ok(NOT has_table_privilege('service_role','firstten_private.guest_marketing_plans','SELECT,INSERT,UPDATE,DELETE'),'service role uses fixed RPC only');
SELECT ok(NOT has_table_privilege('service_role','firstten_private.guest_marketing_operations','SELECT,INSERT,UPDATE,DELETE'),'save receipts are closed');
SELECT ok(NOT has_function_privilege('anon','public.load_guest_marketing_plan(text,uuid)','EXECUTE'),'anonymous direct RPC denied');
