SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gmh_session('a'),'fc240000-0000-4000-8000-000000000012','team_shared',0,gen_random_uuid(),true,firstten_policy_test.gmh_doc())->>'ok','true','save distinct shared plan without teacher grant');
RESET ROLE;
CREATE FUNCTION firstten_policy_test.gmh_spec(request uuid DEFAULT 'fc240000-0000-4000-8000-000000000020',rev bigint DEFAULT 1)RETURNS jsonb LANGUAGE sql STABLE AS $$
SELECT jsonb_build_object('planId','fc240000-0000-4000-8000-000000000011','expectedPlanRevision',rev,'assignmentId','fc240000-0000-4000-8000-000000000002','threadId','fc240000-0000-4000-8000-000000000003','requestId',request,'selections',jsonb_build_array(jsonb_build_object('kind','audience','recordId','fc240000-0000-4000-8000-000000000011'),jsonb_build_object('kind','content','recordId','fc240000-0000-4000-8000-000000000102','excerpt','END_OF_DEMO_DRAFT')),'redactions',jsonb_build_array('Fictional student builders'),'reflection',jsonb_build_object('title','Fictional Élodie marketing handoff','interpretation','Authored learning, not measured demand','uncertainty','No real test','decision','Revise','nextAction','One permitted test'));
$$;
CREATE FUNCTION firstten_policy_test.gmh_confirm(label text,request uuid DEFAULT gen_random_uuid(),affirm boolean DEFAULT true)RETURNS jsonb LANGUAGE sql AS $$SELECT public.confirm_guest_marketing_submission(firstten_policy_test.gmh_session('a'),(SELECT(result#>>'{data,id}')::uuid FROM firstten_policy_test.gmh_results WHERE gmh_results.label=$1),(SELECT result#>>'{data,hash}'FROM firstten_policy_test.gmh_results WHERE gmh_results.label=$1),request,affirm)$$;
CREATE FUNCTION firstten_policy_test.gmh_id(label text)RETURNS uuid LANGUAGE sql STABLE AS $$SELECT(result#>>'{data,id}')::uuid FROM firstten_policy_test.gmh_results WHERE gmh_results.label=$1$$;
GRANT EXECUTE ON FUNCTION firstten_policy_test.gmh_spec(uuid,bigint),firstten_policy_test.gmh_confirm(text,uuid,boolean),firstten_policy_test.gmh_id(text)TO authenticated,service_role;
